const fs=require('node:fs');
const expected='releases/2ae5c2de90997e3c07318664c0462e89dd25fbfb/app';
const actual=fs.readlinkSync('/srv/projects/Sexshop/current');
const results={scope:'production-readonly',expected,active:actual,checks:[]};
(async()=>{
 const pages=['/','/catalogo'];
 for(let i=0;i<pages.length;i++){
  const path=pages[i];
  const r=await fetch('https://sevelora.eu'+path,{signal:AbortSignal.timeout(12000)});
  const h=await r.text();
  const tags=[...h.matchAll(/<a\b[^>]*>/gi)].map(m=>m[0]);
  const out=tags.filter(x=>x.includes('awin1.com/pclick.php'));
  const bad=out.filter(x=>/target\s*=\s*["']_blank/i.test(x)||!/rel="[^"]*sponsored[^"]*"/i.test(x));
  const badUrls=out.filter(t=>{const m=t.match(/href="([^"]+)"/);if(!m)return true;try{const u=new URL(m[1].replace(/&amp;/g,'&'));return u.hostname!=='www.awin1.com'||u.pathname!=='/pclick.php'||u.searchParams.get('a')!=='3157353'||u.searchParams.get('m')!=='37722'}catch{return true}});
  results.checks.push({path,status:r.status,affiliateLinks:out.length,popupTargets:bad.length,badAffiliateUrls:badUrls.length});
  if(path==='/catalogo'){const m=h.match(/href="(\/produto\/\d+)"/);if(m)pages.push(m[1])}
 }
 console.log(JSON.stringify(results));
 if(actual!==expected||results.checks.length!==3||results.checks.some(x=>x.status!==200||x.affiliateLinks===0||x.popupTargets!==0||x.badAffiliateUrls!==0))process.exitCode=9;
})().catch(e=>{console.error('PUBLIC_CHECK_FAILED:'+e.message);process.exitCode=9});
